        private final Binary[][] deviceArray = containsGreaterThan && !deviceEqual ? new Binary[][] { new Binary[] { d2, d2 }, new Binary[] { d2, d2 }, new Binary[] { d1, d1, d1 }, new Binary[] { d1, d1, d1 } } : new Binary[][] { new Binary[] { d1, d1, d1 }, new Binary[] { d1, d1, d1 }, new Binary[] { d2, d2 }, new Binary[] { d2, d2 } };

        private final int[][] valueArray = containsGreaterThan ? (deviceEqual ? new int[][] { { 100, 50, 40 }, { 30, 20, 10 }, { 270, 260 }, { 160, 130 } } : new int[][] { { 270, 260 }, { 160, 130 }, { 100, 50, 40 }, { 30, 20, 10 } }) : new int[][] { { 10, 20, 30 }, { 40, 50, 100 }, { 130, 160 }, { 260, 270 } };

        private final boolean[][][] valueIsNull = containsGreaterThan && !deviceEqual ? new boolean[][][] { { { false, false }, { false, false }, { false, false, false }, { false, false, false } } } : new boolean[][][] { { { false, false, false }, { false, false, false }, { false, false }, { false, false } } };

