        public long calculateRetainedSizeAfterCallingNext() {
            return 0;
        }

        @Override
        public long ramBytesUsed() {
            return 0;
        }
    };
    AsofMergeSortInnerJoinOperator asofInnerJoinOperator = new AsofMergeSortInnerJoinOperator(operatorContext, leftChild, deviceEqual ? new int[] { 1, 0 } : new int[] { 0 }, new int[] { 0, 2 }, rightChild, deviceEqual ? new int[] { 1, 0 } : new int[] { 0 }, new int[] { 0, 2 }, JoinKeyComparatorFactory.getAsofComparators(deviceEqual ? Collections.singletonList(BinaryType.TEXT) : Collections.emptyList(), ignoreEqual, !containsGreaterThan), Arrays.asList(TSDataType.TIMESTAMP, TSDataType.INT32, TSDataType.TIMESTAMP, TSDataType.INT32));
    try {
        int count = 0;
        ListenableFuture<?> listenableFuture = asofInnerJoinOperator.isBlocked();
        listenableFuture.get();
        while (!asofInnerJoinOperator.isFinished() && asofInnerJoinOperator.hasNext()) {
            TsBlock tsBlock = asofInnerJoinOperator.next();
            if (tsBlock != null && !tsBlock.isEmpty()) {
                for (int i = 0, size = tsBlock.getPositionCount(); i < size; i++, count++) {
                    assertEquals(time1Array[count], tsBlock.getColumn(0).getLong(i));
